/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// PaffH 04.11.25
/// last modified: PaffH 05.12.25
/// </summary>
/// <param name = "_nDXBVEMailRequestHeader">NDXBVEMailRequestHeader</param>
/// <returns>NDXBVEMailRequestAIDBHeaderTmp</returns>
public static NDXBVEMailRequestAIDBHeaderTmp fillFromNDXBVEMailRequestHeader(NDXBVEMailRequestHeader _nDXBVEMailRequestHeader)
{
    NDXBVEMailRequestAIDBHeaderTmp nDXBVEMailRequestAIDBHeaderTmp;
    str sectionIdentifier;

    // entire document
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::HeaderAIDBDocument;
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = "@NDX:NDXAIDBEntireDocument";
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // E-Mail
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Email;
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, _nDXBVEMailRequestHeader.EmailFrom);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // request
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Request;
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, _nDXBVEMailRequestHeader.RequestIdentifier);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // contact person
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::ContactPerson;
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, _nDXBVEMailRequestHeader.ContactPersonName);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // Organisation            
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Organisation;
    sectionIdentifier = '';
    if (_nDXBVEMailRequestHeader.OrganisationName1 || _nDXBVEMailRequestHeader.OrganisationName2 || _nDXBVEMailRequestHeader.OrganisationName3)
    {
        sectionIdentifier = strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, _nDXBVEMailRequestHeader.OrganisationName1, _nDXBVEMailRequestHeader.OrganisationName2, _nDXBVEMailRequestHeader.OrganisationName3);
    }
    if (!sectionIdentifier && (_nDXBVEMailRequestHeader.OrganisationAddressZipCode|| _nDXBVEMailRequestHeader.OrganisationAddressCity))
    {
        sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, _nDXBVEMailRequestHeader.OrganisationAddressZipCode, _nDXBVEMailRequestHeader.OrganisationAddressCity);
    }
    if (!sectionIdentifier && (_nDXBVEMailRequestHeader.OrganisationCustomerDataAreaId || _nDXBVEMailRequestHeader.OrganisationCustomerAccount))
    {
        sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, _nDXBVEMailRequestHeader.OrganisationCustomerDataAreaId, _nDXBVEMailRequestHeader.OrganisationCustomerAccount);
    }
    if (!sectionIdentifier && (_nDXBVEMailRequestHeader.OrganisationProspectDataAreaId || _nDXBVEMailRequestHeader.OrganisationProspectProspectId))
    {
        sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, _nDXBVEMailRequestHeader.OrganisationProspectDataAreaId, _nDXBVEMailRequestHeader.OrganisationProspectProspectId);
    }
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // Project
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Project;
    sectionIdentifier = _nDXBVEMailRequestHeader.ProjectIdentifier;
    if (!sectionIdentifier && (_nDXBVEMailRequestHeader.ProjectAddressZipCode || _nDXBVEMailRequestHeader.ProjectAddressCity))
    {
        sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, _nDXBVEMailRequestHeader.ProjectAddressZipCode, _nDXBVEMailRequestHeader.ProjectAddressCity);
    }
    if (!sectionIdentifier)
    {
        sectionIdentifier = _nDXBVEMailRequestHeader.ProjectAddressStreet;
    }
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // Demand
    nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, _nDXBVEMailRequestHeader);
    nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Demand;
    nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, _nDXBVEMailRequestHeader.DemandQuotationDeliveryDate);
    nDXBVEMailRequestAIDBHeaderTmp.insert();

    // building owner
    NDXBVEMailRequestBuildingOwner nDXBVEMailRequestBuildingOwner;
    while select nDXBVEMailRequestBuildingOwner
        order by nDXBVEMailRequestBuildingOwner.IdentifierLine
        where nDXBVEMailRequestBuildingOwner.IdentifierGUID == _nDXBVEMailRequestHeader.IdentifierGUID
    {
        nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, nDXBVEMailRequestBuildingOwner);
        nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::BuildingOwner;

        sectionIdentifier = '';
        if (nDXBVEMailRequestBuildingOwner.Name1 || nDXBVEMailRequestBuildingOwner.Name2 || nDXBVEMailRequestBuildingOwner.Name3)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, nDXBVEMailRequestBuildingOwner.Name1, nDXBVEMailRequestBuildingOwner.Name2, nDXBVEMailRequestBuildingOwner.Name3);
        }
        if (!sectionIdentifier && (nDXBVEMailRequestBuildingOwner.AddressZipCode || nDXBVEMailRequestBuildingOwner.AddressCity))
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, nDXBVEMailRequestBuildingOwner.AddressZipCode, nDXBVEMailRequestBuildingOwner.AddressCity);
        }
        nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
        nDXBVEMailRequestAIDBHeaderTmp.insert();
    }

    // planer
    NDXBVEMailRequestPlaner nDXBVEMailRequestPlaner;
    while select nDXBVEMailRequestPlaner
        order by nDXBVEMailRequestPlaner.IdentifierLine
        where nDXBVEMailRequestPlaner.IdentifierGUID == _nDXBVEMailRequestHeader.IdentifierGUID
    {
        nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, nDXBVEMailRequestPlaner);
        nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Planer;
        sectionIdentifier = '';
        if (nDXBVEMailRequestPlaner.Name1 || nDXBVEMailRequestPlaner.Name2 || nDXBVEMailRequestPlaner.Name3)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, nDXBVEMailRequestPlaner.Name1, nDXBVEMailRequestPlaner.Name2, nDXBVEMailRequestPlaner.Name3);
        }
        if (!sectionIdentifier && (nDXBVEMailRequestPlaner.AddressZipCode || nDXBVEMailRequestPlaner.AddressCity))
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, nDXBVEMailRequestPlaner.AddressZipCode, nDXBVEMailRequestPlaner.AddressCity);
        }
        nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
        nDXBVEMailRequestAIDBHeaderTmp.insert();
    }

    // installer
    NDXBVEMailRequestInstaller nDXBVEMailRequestInstaller;
    while select nDXBVEMailRequestInstaller
        order by nDXBVEMailRequestInstaller.IdentifierLine
        where nDXBVEMailRequestInstaller.IdentifierGUID == _nDXBVEMailRequestHeader.IdentifierGUID
    {
        nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, nDXBVEMailRequestInstaller);
        nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::Installer;
        sectionIdentifier = '';
        if (nDXBVEMailRequestInstaller.Name1 || nDXBVEMailRequestInstaller.Name2 || nDXBVEMailRequestInstaller.Name3)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, nDXBVEMailRequestInstaller.Name1, nDXBVEMailRequestInstaller.Name2, nDXBVEMailRequestInstaller.Name3);
        }
        if (!sectionIdentifier && (nDXBVEMailRequestInstaller.AddressZipCode || nDXBVEMailRequestInstaller.AddressCity))
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, nDXBVEMailRequestInstaller.AddressZipCode, nDXBVEMailRequestInstaller.AddressCity);
        }
        nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
        nDXBVEMailRequestAIDBHeaderTmp.insert();
    }

    // ada
    NDXBVEMailRequestADA nDXBVEMailRequestADA;
    while select nDXBVEMailRequestADA
        order by nDXBVEMailRequestADA.IdentifierLine
        where nDXBVEMailRequestADA.IdentifierGUID == _nDXBVEMailRequestHeader.IdentifierGUID
    {
        nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, nDXBVEMailRequestADA);
        nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::ADA;
        sectionIdentifier = '';
        if (nDXBVEMailRequestADA.OrganisationName1 || nDXBVEMailRequestADA.OrganisationName2 || nDXBVEMailRequestADA.OrganisationName3)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, nDXBVEMailRequestADA.OrganisationName1, nDXBVEMailRequestADA.OrganisationName2, nDXBVEMailRequestADA.OrganisationName3);
        }
        if (!sectionIdentifier && (nDXBVEMailRequestADA.OrganisationAddressZipCode || nDXBVEMailRequestADA.OrganisationAddressCity))
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstSpaceSecond, nDXBVEMailRequestADA.OrganisationAddressZipCode, nDXBVEMailRequestADA.OrganisationAddressCity);
        }
        nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::PlaceHolder, sectionIdentifier);
        nDXBVEMailRequestAIDBHeaderTmp.insert();
    }

    //item line
    NDXBVEMailRequestLine nDXBVEMailRequestLine;
    NDXBVEMailRequestLineAIDecisionBasis nDXBVEMailRequestLineAIDecisionBasis;
    while select nDXBVEMailRequestLine
        order by nDXBVEMailRequestLine.IdentifierLine
        where nDXBVEMailRequestLine.IdentifierGUID == _nDXBVEMailRequestHeader.IdentifierGUID
        outer join nDXBVEMailRequestLineAIDecisionBasis
        where nDXBVEMailRequestLineAIDecisionBasis.NDXBVEMailRequestLine == nDXBVEMailRequestLine.RecId
    {
        nDXBVEMailRequestAIDBHeaderTmp = NDXBVEMailRequestAIDBHeaderTmp::initFromTable(nDXBVEMailRequestAIDBHeaderTmp, nDXBVEMailRequestLine);
        nDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType = NDXBVEmailRequestSectionType::ItemLine;
        sectionIdentifier = nDXBVEMailRequestLine.ItemIdentifier;
        if (!sectionIdentifier && nDXBVEMailRequestLine.ItemIdAI)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, nDXBVEMailRequestLine.ItemIdDataAreaIdAI, nDXBVEMailRequestLine.ItemIdAI);
        }
        if (!sectionIdentifier && nDXBVEMailRequestLine.ItemId)
        {
            sectionIdentifier = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, nDXBVEMailRequestLine.ItemIdDataAreaId, nDXBVEMailRequestLine.ItemId);
        }
        if (!sectionIdentifier && nDXBVEMailRequestLineAIDecisionBasis.AIDBDocument)
        {
            sectionIdentifier = subStr(nDXBVEMailRequestLineAIDecisionBasis.AIDBDocument, 1, 50);
        }
        nDXBVEMailRequestAIDBHeaderTmp.SectionIdentifier = strFmt(NDXPlaceholderConstants::FirstInBrackets2, nDXBVEMailRequestLine.IdentifierLine, sectionIdentifier);
        nDXBVEMailRequestAIDBHeaderTmp.insert();
    }

    return nDXBVEMailRequestAIDBHeaderTmp;
}

/// <summary>
/// PaffH 04.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestAIDBHeaderTmp">NDXBVEMailRequestAIDBHeaderTmp</param>
/// <param name = "_table">common</param>
/// <param name = "_clear">default: true</param>
/// <returns>NDXBVEMailRequestAIDBHeaderTmp</returns>
public static NDXBVEMailRequestAIDBHeaderTmp initFromTable(NDXBVEMailRequestAIDBHeaderTmp _nDXBVEMailRequestAIDBHeaderTmp, Common _table, boolean _clear = true)
{
    if (_clear)
    {
        _nDXBVEMailRequestAIDBHeaderTmp.clear();
    }
    _nDXBVEMailRequestAIDBHeaderTmp.RefRecId = _table.RecId;
    _nDXBVEMailRequestAIDBHeaderTmp.RefTableId = _table.TableId;

    return _nDXBVEMailRequestAIDBHeaderTmp;
}
